import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 보고서 유형별 발령 구분 매핑 (null이면 전체). 유형 전체 집합은 미정이라 개발 중 정함
const REPORT_TYPES: Record<string, string | null> = {
  '승진현황': '승진',
  '전보현황': '전보',
  '전체현황': null,
};

const DATE_RE = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;

// 가정: 이력은 처리완료된 발령 건만 누적 대상으로 본다
const HISTORY_WHERE = `status = '처리완료'
  AND (CAST(:startDate AS date) IS NULL OR appointment_date >= CAST(:startDate AS date))
  AND (CAST(:endDate AS date) IS NULL OR appointment_date <= CAST(:endDate AS date))
  AND (CAST(:appointmentType AS text) IS NULL OR appointment_type = CAST(:appointmentType AS text))
  AND (CAST(:departmentId AS bigint) IS NULL OR department_id = CAST(:departmentId AS bigint))
  AND (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))`;

function textOf(v: unknown): string | null {
  return typeof v === 'string' && v !== '' ? v : null;
}

function searchOf(q: Record<string, unknown>, withEmployee: boolean) {
  const bad = (message: string) => new ApiError(422, 'INVALID_SEARCH_CONDITION', message);
  const startDate = textOf(q['startDate']);
  const endDate = textOf(q['endDate']);
  if (startDate !== null && !DATE_RE.test(startDate)) {
    throw bad('발령일자 시작일 형식이 올바르지 않습니다.');
  }
  if (endDate !== null && !DATE_RE.test(endDate)) {
    throw bad('발령일자 종료일 형식이 올바르지 않습니다.');
  }
  if (startDate !== null && endDate !== null && startDate > endDate) {
    throw bad('시작일이 종료일보다 늦을 수 없습니다.');
  }
  const appointmentType = textOf(q['appointmentType']);
  if (appointmentType !== null && appointmentType.length > 50) {
    throw bad('발령 구분이 너무 깁니다.');
  }
  const departmentId = textOf(q['departmentId']);
  if (departmentId !== null && !/^\d{1,18}$/.test(departmentId)) {
    throw bad('부서 ID 형식이 올바르지 않습니다.');
  }
  const employeeId = withEmployee ? textOf(q['employeeId']) : null;
  if (employeeId !== null && !/^\d{1,18}$/.test(employeeId)) {
    throw bad('임직원 ID 형식이 올바르지 않습니다.');
  }
  return { startDate, endDate, appointmentType, departmentId, employeeId };
}

function pagingOf(q: Record<string, unknown>) {
  const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
  const size = q['size'] === undefined || q['size'] === '' ? 20 : Number(q['size']);
  if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
  }
  return { page, size: Math.min(size, 200) };
}

@Controller('api/v1')
export class FnSfr01305Controller {
  @Get('/personnel-appointments/history')
  async listPersonnelAppointmentHistory(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const q = checks.queryOf(req.query);
    const cond = searchOf(q, true);
    const paging = pagingOf(q);
    return transaction(async (db) => {
      const params = { ...cond, limit: paging.size, offset: paging.page * paging.size };
      const items = await db.query(
        `SELECT personnel_appointment_id AS "personnelAppointmentId",
  employee_id AS "employeeId",
  appointment_type AS "appointmentType",
  appointment_date AS "appointmentDate",
  new_position_name AS "newPositionName",
  processed_date AS "processedDate"
FROM personnel_appointment
WHERE ${HISTORY_WHERE}
ORDER BY appointment_date DESC, personnel_appointment_id DESC
LIMIT :limit OFFSET :offset`,
        params,
      );
      const totals = await db.query(
        `SELECT COUNT(*) AS "total" FROM personnel_appointment WHERE ${HISTORY_WHERE}`,
        cond,
      );
      return { items, page: paging.page, size: paging.size, total: Number(totals[0]['total']) };
    });
  }

  @Get('/personnel-appointments/summary')
  async getPersonnelAppointmentSummary(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const q = checks.queryOf(req.query);
    const cond = searchOf(q, false);
    const paging = pagingOf(q);
    return transaction(async (db) => {
      const params = { ...cond, limit: paging.size, offset: paging.page * paging.size };
      const items = await db.query(
        `SELECT appointment_type AS "appointmentType", COUNT(*) AS "count"
FROM personnel_appointment
WHERE ${HISTORY_WHERE}
GROUP BY appointment_type
ORDER BY appointment_type
LIMIT :limit OFFSET :offset`,
        params,
      );
      const totals = await db.query(
        `SELECT COUNT(*) AS "total" FROM (
  SELECT appointment_type FROM personnel_appointment WHERE ${HISTORY_WHERE} GROUP BY appointment_type
) g`,
        cond,
      );
      return {
        items: items.map((r: Record<string, unknown>) => ({ appointmentType: r['appointmentType'], count: Number(r['count']) })),
        page: paging.page,
        size: paging.size,
        total: Number(totals[0]['total']),
      };
    });
  }

  @Get('/personnel-appointments/reports')
  async getPersonnelAppointmentReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const q = checks.queryOf(req.query);
    const reportType = textOf(q['reportType']);
    if (reportType === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '보고서 유형을 선택하세요.');
    }
    if (!Object.prototype.hasOwnProperty.call(REPORT_TYPES, reportType)) {
      throw new ApiError(422, 'INVALID_REPORT_TYPE', '지원하지 않는 보고서 유형입니다.');
    }
    const startDate = textOf(q['startDate']);
    const endDate = textOf(q['endDate']);
    if ((startDate !== null && !DATE_RE.test(startDate)) || (endDate !== null && !DATE_RE.test(endDate))) {
      throw new ApiError(422, 'INVALID_REPORT_TYPE', '조회 조건 형식이 올바르지 않습니다.');
    }
    if (startDate !== null && endDate !== null && startDate > endDate) {
      throw new ApiError(422, 'INVALID_REPORT_TYPE', '시작일이 종료일보다 늦을 수 없습니다.');
    }
    const appointmentType = REPORT_TYPES[reportType];
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT personnel_appointment_id AS "personnelAppointmentId",
  employee_id AS "employeeId",
  department_id AS "departmentId",
  appointment_type AS "appointmentType",
  appointment_date AS "appointmentDate",
  new_position_name AS "newPositionName"
FROM personnel_appointment
WHERE status = '처리완료'
  AND (CAST(:startDate AS date) IS NULL OR appointment_date >= CAST(:startDate AS date))
  AND (CAST(:endDate AS date) IS NULL OR appointment_date <= CAST(:endDate AS date))
  AND (CAST(:appointmentType AS text) IS NULL OR appointment_type = CAST(:appointmentType AS text))
ORDER BY appointment_date DESC, personnel_appointment_id DESC`,
        { startDate, endDate, appointmentType },
      );
      return { reportType, rows };
    });
  }
}

