import { useState } from 'react';
import {
  call,
  useData,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const REPORT_OPTIONS: [string, string][] = [
  ['승진현황', '승진현황'],
  ['전보현황', '전보현황'],
  ['전체현황', '전체현황'],
];

export default function FnSfr01305Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [appointmentType, setAppointmentType] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [formError, setFormError] = useState('');
  const [reportOpen, setReportOpen] = useState(false);
  const [reportType, setReportType] = useState('');
  const [reportStart, setReportStart] = useState('');
  const [reportEnd, setReportEnd] = useState('');
  const [reportRows, setReportRows] = useState<Row[] | undefined>(undefined);

  const history = useData<Page>(
    () => call<Page>('GET', '/personnel-appointments/history', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page],
  );
  const summary = useData<Page>(
    () => call<Page>('GET', '/personnel-appointments/summary', role, undefined, { ...applied, size: 200 }),
    [applied],
  );

  function search() {
    if (startDate !== '' && endDate !== '' && startDate > endDate) {
      setFormError('시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ startDate, endDate, appointmentType, departmentId, employeeId });
  }

  function reset() {
    setStartDate('');
    setEndDate('');
    setAppointmentType('');
    setDepartmentId('');
    setEmployeeId('');
    setFormError('');
    setPage(0);
    setApplied({});
  }

  async function makeReport() {
    if (reportType === '') {
      throw new Error('보고서 유형을 선택하세요.');
    }
    if (reportStart !== '' && reportEnd !== '' && reportStart > reportEnd) {
      throw new Error('시작일이 종료일보다 늦을 수 없습니다.');
    }
    const result = await call<{ reportType: string; rows: Row[] }>(
      'GET',
      '/personnel-appointments/reports',
      role,
      undefined,
      { reportType, startDate: reportStart, endDate: reportEnd },
    );
    setReportRows(result.rows);
    notify('보고서를 생성했습니다.');
  }

  const summaryItems = summary.data ? summary.data.items.slice(0, 4) : [];
  const columns = [
    { key: 'appointmentDate', label: '발령일자', render: (r: Row) => <DateText value={r['appointmentDate']} /> },
    { key: 'employeeId', label: '대상 임직원', render: (r: Row) => <RefName table="employee" role={role} value={r['employeeId']} /> },
    { key: 'appointmentType', label: '발령 구분' },
    { key: 'newPositionName', label: '발령 후 직위' },
    { key: 'processedDate', label: '처리일자', render: (r: Row) => <DateText value={r['processedDate']} /> },
  ];
  const reportColumns = [
    { key: 'appointmentDate', label: '발령일자', render: (r: Row) => <DateText value={r['appointmentDate']} /> },
    { key: 'employeeId', label: '대상 임직원', render: (r: Row) => <RefName table="employee" role={role} value={r['employeeId']} /> },
    { key: 'appointmentType', label: '발령 구분' },
    { key: 'departmentId', label: '발령 후 소속 부서', render: (r: Row) => <RefName table="department" role={role} value={r['departmentId']} /> },
    { key: 'newPositionName', label: '발령 후 직위' },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>발령 현황</h2>
        {summary.error !== '' && <ErrorText text={summary.error} />}
        {summary.data && summary.data.items.length === 0 && <p>데이터가 없습니다.</p>}
        <Tiles
          items={summaryItems.map((r): [string, React.ReactNode] => [
            String(r['appointmentType']),
            <Num value={r['count']} />,
          ])}
        />
      </section>
      <section className="box span-12">
        <h2>발령 이력</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="발령일자 조회 시작일">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="발령일자 조회 종료일">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="발령 구분">
            <TextInput value={appointmentType} onChange={setAppointmentType} />
          </Field>
          <Field label="발령 후 소속 부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
          <Field label="대상 임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
        {history.error !== '' && <ErrorText text={history.error} />}
        <Band total={history.data ? history.data.total : 0}>
          <button
            type="button"
            onClick={() => {
              setReportRows(undefined);
              setReportOpen(true);
            }}
          >
            보고서 생성
          </button>
        </Band>
        <DataTable
          columns={columns}
          rows={history.data ? history.data.items : []}
          empty="조건에 해당하는 데이터가 없습니다."
        />
        <Pager page={page} size={SIZE} total={history.data ? history.data.total : 0} onPage={setPage} />
      </section>
      {reportOpen && (
        <Drawer title="인사발령 현황 보고서" onClose={() => setReportOpen(false)}>
          <Form onSubmit={makeReport} submit="생성">
            <Field label="보고서 유형" required>
              <Select value={reportType} onChange={setReportType} options={REPORT_OPTIONS} />
            </Field>
            <Field label="발령일자 조회 시작일">
              <DateInput value={reportStart} onChange={setReportStart} />
            </Field>
            <Field label="발령일자 조회 종료일">
              <DateInput value={reportEnd} onChange={setReportEnd} />
            </Field>
          </Form>
          {reportRows && (
            <DataTable columns={reportColumns} rows={reportRows} empty="조건에 해당하는 데이터가 없습니다." />
          )}
        </Drawer>
      )}
    </div>
  );
}
